svg.script:
(() => {
    'use strict';
    const root = document.documentElement;
    const layer = document.getElementById('logotype');
    const fallback = document.getElementById('fallback');
    const definitions = document.getElementById('flap-definitions');
    const word = 'infrastructure';
    const count = word.length - 2;
    const params = new URLSearchParams(window.location.search);
    const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
    const numeric = (value, min, max, fallback) => Number.isFinite(Number(value))
        ? clamp(Number(value), min, max) : fallback;
    const variant = Math.round(numeric(params.get('variant') || 0, 0, 6, 0));
    const flagVariant = variant === 5 || variant === 6;
    const swapVariant = variant === 6;
    const flagFace = '@eu-flag';
    // Permanent counter cards add two places even after every letter is revealed.
    const capacity = word.length + (flagVariant ? 2 : 1);
    const lastModelStep = count;
    const preview = params.get('preview') === '1';
    const motionPreference = matchMedia('(prefers-reduced-motion: reduce)');
    const clock = () => performance.timeOrigin + performance.now();
    const mix = (a, b, progress) => a + (b - a) * progress;
    function normalizeColor(value) {
        if (typeof value !== 'string') return null;
        const hex = value.trim().toLowerCase();
        if (/^#[\da-f]{3}$/.test(hex)) return '#' + [...hex.slice(1)].map(digit => digit + digit).join('');
        return /^#[\da-f]{6}$/.test(hex) ? hex : null;
    }
    const milliseconds = value => parseFloat(value) * (/ms\s*$/.test(value) ? 1 : 1000);
    let config, ease, duration, characterAdvance, flapAdvance, glyphWidth, tileWidth, tileHeight, baseline;
    let flagArtwork, joinedFlag, solidClips = [];
    let models = [], sprites = new Map();
    let playing = false, position = 0, startedAt = 0, originTime = 0, frame = 0;
    let lastPublished = -Infinity, ready = false;

    function create(tag, attributes = {}, parent = layer) {
        const element = document.createElementNS('http://www.w3.org/2000/svg', tag);
        for (const [name, value] of Object.entries(attributes)) element.setAttribute(name, value);
        parent.append(element);
        return element;
    }

    function readDefaults() {
        const css = getComputedStyle(root);
        const value = name => css.getPropertyValue(name).trim();
        return {
            transitionDuration: milliseconds(value('--transition-duration')),
            holdDuration: milliseconds(value('--hold-duration')),
            easing: value('--easing'), fontSize: parseFloat(value('--font-size')),
            characterSpacing: parseFloat(value('--character-spacing')),
            flapWidth: numeric(parseFloat(value('--flap-width')), 0.6, 2, 0.85),
            flapHeight: parseFloat(value('--flap-height')),
            flapGap: parseFloat(value('--flap-gap')),
            flapOuterGap: numeric(parseFloat(value('--flap-outer-gap')), 0, 96, 4),
            leadingFlagGap: numeric(parseFloat(value('--leading-flag-gap')), 0, 96, 16),
            starScale: numeric(value('--eu-star-scale') || 1, 0.25, 4, 1),
            flapColor: normalizeColor(value('--flap-color')) || '#003399',
            detailColor: normalizeColor(value('--flap-detail-color')) || '#ffffff',
            detailOpacity: numeric(value('--flap-detail-opacity') || 1, 0, 1, 1),
            detailsVisible: value('--flap-details-visible') !== '0',
            backgroundColor: normalizeColor(value('--background-color')) || '#ffffff',
            loop: value('--loop') === '1',
        };
    }

    // One easing function drives position, opacity, and the two-stage hinge.
    // Bisection solves CSS cubic-bezier's x coordinate, rather than treating
    // its parameter as elapsed time. Reject unsupported curves atomically.
    function easingFor(value) {
        const presets = {
            linear: [0, 0, 1, 1], ease: [0.25, 0.1, 0.25, 1],
            'ease-in': [0.42, 0, 1, 1], 'ease-out': [0, 0, 0.58, 1],
            'ease-in-out': [0.42, 0, 0.58, 1],
        };
        const match = /^cubic-bezier\(([^)]+)\)$/.exec(value);
        const points = presets[value] || (match && match[1].split(',').map(Number));
        if (!points || points.length !== 4 || !points.every(Number.isFinite)
            || points.some(number => number < 0 || number > 1)) return null;
        const [x1, y1, x2, y2] = points;
        const curve = (t, a, b) => 3 * (1 - t) ** 2 * t * a + 3 * (1 - t) * t * t * b + t ** 3;
        return progress => {
            if (progress <= 0 || progress >= 1) return clamp(progress, 0, 1);
            let low = 0, high = 1;
            for (let i = 0; i < 24; i++) {
                const middle = (low + high) / 2;
                if (curve(middle, x1, x2) < progress) low = middle;
                else high = middle;
            }
            return curve((low + high) / 2, y1, y2);
        };
    }

    function stateAt(remaining, padded = variant > 0) {
        if (!remaining) return word;
        const digits = padded ? String(remaining).padStart(2, '0') : String(remaining);
        return word[0] + digits + word.slice(remaining + 1);
    }

    function layout(remaining, swapped = false) {
        const state = new Map();
        if (variant === 3 || variant === 4) {
            const text = stateAt(remaining);
            const cells = variant === 4 ? text.padEnd(capacity, ' ') : text;
            [...cells].forEach((character, index) => state.set(`cell:${index}`, { character, x: index * flapAdvance }));
        } else {
            // Every split-flap counter keeps two digits. At zero, persistent
            // counter places turn directly into flag faces below.
            const digits = remaining ? String(remaining).padStart(variant > 0 ? 2 : 1, '0')
                : flagVariant ? '00' : '';
            const digitWidth = variant === 0 ? glyphWidth : tileWidth;
            const digitAdvance = variant === 0 ? characterAdvance : swapped ? tileWidth : flapAdvance;
            const counterWidth = digits.length ? digitWidth + (digits.length - 1) * digitAdvance : 0;
            // Flap boundaries have their own spacing. After the flag leads,
            // the i joins the plain word, so its next gap uses letter tracking.
            const outerGap = swapped ? config.leadingFlagGap
                : variant > 0 && digits.length ? config.flapOuterGap : config.characterSpacing;
            const counterX = glyphWidth + outerGap;
            const suffixX = swapped ? counterWidth + outerGap + characterAdvance
                : digits.length ? counterX + counterWidth + outerGap : characterAdvance;
            state.set('letter:0', { character: word[0], x: swapped ? counterWidth + outerGap : 0 });
            for (let index = remaining + 1; index < word.length; index++) {
                state.set(`letter:${index}`, { character: word[index], x: suffixX + (index - remaining - 1) * characterAdvance });
            }
            [...digits].forEach((character, index) => state.set(`digit:${index}`, {
                character: flagVariant && remaining === 0 ? flagFace : character,
                x: (swapped ? 0 : counterX) + index * digitAdvance,
            }));
        }
        return state;
    }

    function makeFlagArtwork() {
        // One shared circle spans both cards. Each half-face clips its own
        // translated copy, so neither the stars nor a background can bridge
        // the existing gap. Fit the EU's 3:2 reference within custom cards.
        const pairWidth = flapAdvance + tileWidth;
        const referenceHeight = Math.min(tileHeight, pairWidth / 1.5);
        const ringRadius = referenceHeight / 3 * config.starScale;
        const starRadius = referenceHeight / 18 * config.starScale;
        const innerRadius = starRadius * Math.sin(Math.PI / 10) / Math.sin(3 * Math.PI / 10);
        const cx = pairWidth / 2, cy = tileHeight / 2;
        const stars = flagArtwork = create('g', {
            id: 'eu-flag-stars', fill: '#ffcc00', 'data-ring-radius': ringRadius,
            'data-star-radius': starRadius, 'data-center-x': cx, 'data-center-y': cy,
        }, definitions);
        for (let star = 0; star < 12; star++) {
            const angle = -Math.PI / 2 + star * Math.PI / 6;
            const x = cx + ringRadius * Math.cos(angle), y = cy + ringRadius * Math.sin(angle);
            const points = Array.from({ length: 10 }, (_, point) => {
                const radius = point % 2 ? innerRadius : starRadius;
                // Every star points up, independently of its ring position.
                const direction = -Math.PI / 2 + point * Math.PI / 5;
                return `${x + radius * Math.cos(direction)},${y + radius * Math.sin(direction)}`;
            }).join(' ');
            create('polygon', { points, 'data-star': star }, stars);
        }
    }

    function roundedCardPath(x, width, leftRadius, rightRadius) {
        return `M ${x + leftRadius} 0 H ${x + width - rightRadius}
            A ${rightRadius} ${rightRadius} 0 0 1 ${x + width} ${rightRadius}
            V ${tileHeight - rightRadius} A ${rightRadius} ${rightRadius} 0 0 1 ${x + width - rightRadius} ${tileHeight}
            H ${x + leftRadius} A ${leftRadius} ${leftRadius} 0 0 1 ${x} ${tileHeight - leftRadius}
            V ${leftRadius} A ${leftRadius} ${leftRadius} 0 0 1 ${x + leftRadius} 0 Z`;
    }

    function updateFlagGeometry(progress) {
        const originalWidth = tileWidth + flapAdvance;
        const pairWidth = tileWidth + mix(flapAdvance, tileWidth, progress);
        // Keep the whole star circle centred and uniformly scaled as the gap
        // closes. Translating two fixed crops would break the circular artwork.
        const scale = Math.min(tileHeight, pairWidth / 1.5) / Math.min(tileHeight, originalWidth / 1.5);
        flagArtwork.setAttribute('transform', `translate(${pairWidth / 2} ${tileHeight / 2}) scale(${scale}) translate(${-originalWidth / 2} ${-tileHeight / 2})`);
        solidClips.forEach((path, column) => path.setAttribute('d', flapOutline(column, progress)));
        // One uninterrupted final face avoids a raster seam between touching cards.
        joinedFlag.setAttribute('display', progress === 1 ? 'inline' : 'none');
        root.dataset.flagGap = String(pairWidth - 2 * tileWidth);
    }

    function flapOutline(column, progress) {
        const radius = config.fontSize * 0.045;
        return roundedCardPath(0, tileWidth,
            column === 0 ? radius : radius * (1 - progress),
            column === 1 ? radius : radius * (1 - progress));
    }

    function text(character, parent, attributes = {}) {
        const node = create('text', { x: glyphWidth / 2, y: baseline, 'text-anchor': 'middle', ...attributes }, parent);
        node.textContent = character;
        return node;
    }

    function makePlain(parent) {
        const outgoing = text('', parent), incoming = text('', parent);
        return (before, after, progress) => {
            outgoing.textContent = before;
            incoming.textContent = after;
            outgoing.setAttribute('opacity', before === after ? 1 : 1 - progress);
            incoming.setAttribute('opacity', before === after ? 0 : progress);
        };
    }

    function makeFlap(parent, column) {
        const tile = create('g', { 'data-flap': 'true' }, parent);
        if (swapVariant) tile.setAttribute('clip-path', `url(#flap-solid-${column})`);
        const half = tileHeight / 2;
        function face(part) {
            // Transform the wrapper AFTER clipping its child, so the glyph
            // and its half-card rotate together about the centre hinge.
            const wrapper = create('g', {}, tile);
            const clipped = create('g', { 'clip-path': `url(#flap-${part})` }, wrapper);
            const surface = swapVariant ? create('path', { class: 'flap-surface' }, clipped)
                : create('rect', { width: tileWidth, height: tileHeight, rx: config.fontSize * 0.045, class: 'flap-surface' }, clipped);
            const glyph = text('', clipped, { x: tileWidth / 2, class: 'flap-text' });
            const shadow = create('rect', { width: tileWidth, height: tileHeight, fill: '#000', opacity: 0 }, clipped);
            // Artwork belongs to the rotating face, just like the digits.
            // Draw stars above the shade to retain their specified yellow.
            const stars = flagVariant && Number.isInteger(column)
                ? create('use', { href: '#eu-flag-stars', transform: `translate(${-column * flapAdvance} 0)`, display: 'none' }, clipped)
                : null;
            return { wrapper, surface, glyph, shadow, stars };
        }
        function setFace(face, content) {
            const flag = content === flagFace;
            face.glyph.textContent = flag ? '' : content;
            if (face.stars) face.stars.setAttribute('display', flag ? 'inline' : 'none');
        }
        const top = face('top'), bottom = face('bottom');
        const fallingTop = face('top'), arrivingBottom = face('bottom');
        fallingTop.wrapper.dataset.face = 'outgoing-top';
        arrivingBottom.wrapper.dataset.face = 'incoming-bottom';
        const details = create('g', { 'data-flap-details': 'true' }, tile);
        create('rect', { x: 0, y: half - 0.55, width: tileWidth, height: 1.1, class: 'flap-detail' }, details);
        for (const x of [0, tileWidth - 1.5]) {
            create('rect', { x, y: half - 2, width: 1.5, height: 4, rx: 0.5, class: 'flap-detail' }, details);
        }
        // A clean face replaces the entire mechanism, including its shadows
        // and hardware over the stars. Recolouring the seam alone leaves a
        // blue cut through oversized stars. Each card still clips separately.
        const solid = swapVariant ? create('g', {
            'data-solid-flag': 'true', 'clip-path': `url(#flap-solid-${column})`, display: 'none',
        }, tile) : null;
        let solidStars;
        if (solid) {
            create('rect', { width: tileWidth, height: tileHeight, class: 'flap-surface' }, solid);
            solidStars = create('use', { href: '#eu-flag-stars', transform: `translate(${-column * flapAdvance} 0)` }, solid);
        }
        let previousPair = '';
        return (before, after, progress, solidProgress = 0) => {
            const formingFlag = swapVariant && before !== after && after === flagFace;
            details.setAttribute('opacity', formingFlag ? 1 - progress : 1);
            if (solid) {
                // Let the hinge reveal the incoming artwork. A whole-card
                // overlay during this turn would ghost stars over the old digits.
                solid.setAttribute('display', !formingFlag && solidProgress > 0 ? 'inline' : 'none');
                solid.setAttribute('opacity', formingFlag ? 0 : solidProgress);
                const offset = -column * mix(flapAdvance, tileWidth, solidProgress);
                // The face silhouettes close their inner corners too; changing
                // only the outer clip would leave a notch in the blue surfaces.
                for (const face of [top, bottom, fallingTop, arrivingBottom]) {
                    face.surface.setAttribute('d', flapOutline(column, solidProgress));
                }
                for (const stars of [top.stars, bottom.stars, fallingTop.stars, arrivingBottom.stars, solidStars]) {
                    stars.setAttribute('transform', `translate(${offset} 0)`);
                }
            }
            const changing = before !== after;
            const pair = `${before}\0${after}`;
            if (pair !== previousPair) {
                // New top and old bottom are stationary underneath the leaf.
                setFace(top, after);
                setFace(bottom, before);
                setFace(fallingTop, before);
                setFace(arrivingBottom, after);
                previousPair = pair;
            }
            // Orthographic projection of a leaf rotating around its X axis:
            // outgoing top 0..90 degrees, then incoming bottom -90..0.
            const topScale = changing && progress < 0.5 ? Math.cos(progress * Math.PI) : 0;
            const bottomScale = changing && progress >= 0.5 ? Math.sin((progress - 0.5) * Math.PI) : 0;
            fallingTop.wrapper.setAttribute('transform', `translate(0 ${half}) scale(1 ${topScale}) translate(0 ${-half})`);
            arrivingBottom.wrapper.setAttribute('transform', `translate(0 ${half}) scale(1 ${bottomScale}) translate(0 ${-half})`);
            fallingTop.wrapper.setAttribute('display', topScale > 0.00001 ? 'inline' : 'none');
            arrivingBottom.wrapper.setAttribute('display', bottomScale > 0.00001 ? 'inline' : 'none');
            fallingTop.shadow.setAttribute('opacity', (1 - topScale) * 0.28);
            arrivingBottom.shadow.setAttribute('opacity', swapVariant && after === flagFace ? 0 : (1 - bottomScale) * 0.28);
            top.shadow.setAttribute('opacity', swapVariant && after === flagFace ? 0 : 0.025);
            const bottomContent = !changing || progress >= 1 ? after : before;
            bottom.shadow.setAttribute('opacity', swapVariant && bottomContent === flagFace ? 0 : 0.07);
            // Holds (including p=1 when manually sampled) show the new face.
            setFace(bottom, bottomContent);
            tile.dataset.flipping = String(changing && progress > 0 && progress < 1);
            const content = progress < 0.5 ? before : after;
            tile.dataset.empty = String(content === flagFace || content.trim() === '');
            tile.dataset.flag = String(content === flagFace);
        };
    }

    function applyColors() {
        root.style.setProperty('--flap-color', config.flapColor);
        root.style.setProperty('--flap-detail-color', config.detailColor);
        root.style.setProperty('--flap-detail-opacity', String(config.detailOpacity));
        root.style.setProperty('--flap-detail-display', config.detailsVisible ? 'inline' : 'none');
        root.style.setProperty('--background-color', config.backgroundColor);
        // The default and unboxed letters remain readable on shared dark backgrounds.
        const rgb = config.backgroundColor.match(/[\da-f]{2}/gi).map(value => parseInt(value, 16) / 255);
        const light = rgb.map(value => value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4);
        const luminance = light[0] * 0.2126 + light[1] * 0.7152 + light[2] * 0.0722;
        root.style.setProperty('--text-color', luminance > 0.179 ? '#000000' : '#f8faff');
    }

    function build() {
        layer.replaceChildren();
        definitions.replaceChildren();
        sprites = new Map();
        solidClips = [];
        root.style.setProperty('--font-size', `${config.fontSize}px`);
        root.style.setProperty('--character-spacing', `${config.characterSpacing}px`);
        applyColors();
        const measure = create('text');
        measure.textContent = 'M';
        glyphWidth = measure.getComputedTextLength();
        measure.remove();
        tileWidth = config.fontSize * config.flapWidth;
        tileHeight = config.fontSize * (variant === 0 ? 1.42 : config.flapHeight);
        // Text and cards use independent pitches. Changing a card's width
        // shifts the following text block without spreading its letters apart.
        characterAdvance = glyphWidth + config.characterSpacing;
        flapAdvance = tileWidth + config.fontSize * config.flapGap;
        baseline = tileHeight / 2 + config.fontSize * 0.32;
        root.dataset.characterAdvance = String(characterAdvance);
        root.dataset.flapAdvance = String(flapAdvance);
        root.dataset.flapWidth = String(tileWidth);
        root.dataset.flapHeight = String(tileHeight);
        root.dataset.variant = String(variant);
        // The final counter turn also completes the leading flag. Every
        // variant reaches its finished state together, with no extra cycle.
        duration = count * (config.holdDuration + config.transitionDuration) + config.holdDuration;
        ease = easingFor(config.easing) || easingFor('ease-in-out');

        for (const [part, y] of [['top', 0], ['bottom', tileHeight / 2]]) {
            const clip = create('clipPath', { id: `flap-${part}`, clipPathUnits: 'userSpaceOnUse' }, definitions);
            create('rect', { x: 0, y, width: tileWidth, height: tileHeight / 2 }, clip);
        }
        if (swapVariant) {
            for (const column of [0, 1]) {
                const clip = create('clipPath', { id: `flap-solid-${column}`, clipPathUnits: 'userSpaceOnUse' }, definitions);
                solidClips.push(create('path', {}, clip));
            }
            const joinedClip = create('clipPath', { id: 'flag-joined', clipPathUnits: 'userSpaceOnUse' }, definitions);
            create('rect', { width: 2 * tileWidth, height: tileHeight, rx: config.fontSize * 0.045 }, joinedClip);
        }
        if (flagVariant) makeFlagArtwork();
        models = Array.from({ length: count + 1 }, (_, step) => layout(count - step, swapVariant && step === count));
        const keys = new Set(models.flatMap(model => [...model.keys()]));
        for (const key of keys) {
            const group = create('g', { 'data-key': key });
            const digit = key.startsWith('digit:');
            const flapped = variant === 3 || variant === 4 || (variant > 0 && digit);
            sprites.set(key, { group, flapped, draw: flapped ? makeFlap(group, digit ? Number(key.split(':')[1]) : null) : makePlain(group) });
        }
        if (swapVariant) {
            joinedFlag = create('g', { 'data-joined-flag': 'true', 'clip-path': 'url(#flag-joined)', display: 'none' });
            create('rect', { width: 2 * tileWidth, height: tileHeight, class: 'flap-surface' }, joinedFlag);
            create('use', { href: '#eu-flag-stars' }, joinedFlag);
            layer.append(sprites.get('letter:0').group);
        }
        const canvasHeight = preview ? 180 : 1000;
        root.setAttribute('viewBox', `0 0 1000 ${canvasHeight}`);
        root.setAttribute('height', canvasHeight);
        document.getElementById('background').setAttribute('height', canvasHeight);
        // Keep the reference origin in standalone mode; add preview gutters.
        const inset = preview ? 24 : 0;
        // Fit the widest actual state, keeping scale stable across the animation.
        const contentWidth = Math.max(...models.flatMap(model => [...model].map(([key, cell]) =>
            cell.x + (sprites.get(key).flapped ? tileWidth : glyphWidth))));
        const scale = Math.min(1, (1000 - inset * 2) / contentWidth, (canvasHeight - inset * 2) / tileHeight);
        const y = preview ? (canvasHeight - tileHeight * scale) / 2
            : Math.max(0, config.fontSize * 55 / 48 - baseline) * scale;
        layer.setAttribute('transform', `translate(${inset} ${y}) scale(${scale})`);
        root.dataset.fitScale = String(scale);
        root.dataset.contentWidth = String(contentWidth);
        fallback.setAttribute('visibility', 'hidden');
        layer.setAttribute('visibility', 'visible');
    }

    function currentTime() {
        if (!playing) return position;
        const elapsed = originTime + Math.max(0, clock() - startedAt);
        return config.loop ? elapsed % duration : Math.min(duration, elapsed);
    }

    function sample(time) {
        const stepDuration = config.holdDuration + config.transitionDuration;
        const step = Math.min(lastModelStep, Math.floor(time / stepDuration));
        const progress = step === lastModelStep ? 0 : clamp((time - step * stepDuration - config.holdDuration) / config.transitionDuration, 0, 1);
        return { step, progress, eased: ease(progress) };
    }

    function render(time) {
        const { step, progress, eased } = sample(time);
        const swapProgress = swapVariant ? (step === count ? 1 : step === count - 1 ? eased : 0) : 0;
        if (swapVariant) updateFlagGeometry(swapProgress);
        const before = models[step], after = models[Math.min(lastModelStep, step + 1)];
        for (const [key, sprite] of sprites) {
            const from = before.get(key), to = after.get(key);
            if (!from && !to) {
                // visibility:hidden is inherited and a child can override it.
                // Remove the entire retired tile from painting, including old
                // moving half-faces, when stepping forward or scrubbing back.
                sprite.group.setAttribute('display', 'none');
                sprite.group.setAttribute('opacity', 0);
                continue;
            }
            let alpha = from && to ? 1 : from ? 1 - eased : eased;
            let x = mix((from || to).x, (to || from).x, eased);
            if (swapVariant && step === count - 1 && (key === 'letter:0' || key === 'letter:1')) {
                // Reverse the reveal, then fade in beside the moving word.
                // Following its spacing keeps a large final gap from placing
                // the reappearing i over another letter. The baseline stays fixed.
                const firstLetterX = mix(before.get('letter:2').x, after.get('letter:2').x, eased) - 2 * characterAdvance;
                if (key === 'letter:0') {
                    alpha = progress < 0.5 ? ease(1 - 2 * progress) : ease(2 * progress - 1);
                    x = progress < 0.5 ? from.x : firstLetterX;
                } else x = firstLetterX + characterAdvance;
            }
            sprite.group.setAttribute('display', alpha > 0 ? 'inline' : 'none');
            sprite.group.setAttribute('opacity', alpha);
            sprite.group.setAttribute('transform', `translate(${x} 0)`);
            if (!sprite.flapped && (!from || !to)) {
                // The outer opacity already handles a new/removed letter.
                // Avoid applying the easing twice through a second fade.
                const character = (from || to).character;
                sprite.draw(character, character, eased);
            } else sprite.draw(from?.character || '', to?.character || '', eased, swapProgress);
        }
        const remaining = count - Math.min(count, step);
        root.dataset.state = stateAt(remaining);
        root.dataset.displayState = swapVariant && step === count ? '  ' + word
            : flagVariant && remaining === 0 ? word[0] + '  ' + word.slice(1)
            : stateAt(remaining);
        if (swapVariant) root.dataset.swapProgress = String(swapProgress);
    }

    function snapshot() {
        const time = currentTime();
        const { step, progress } = sample(time);
        return {
            type: 'i12e:state', variant, config: { ...config }, duration, currentTime: time, playing,
            step, totalSteps: lastModelStep,
            state: stateAt(count - Math.min(count, step)), reducedMotion: motionPreference.matches,
            ...(flagVariant ? { flagPhase: step >= count ? 'flag' : step === count - 1 && progress > 0 ? 'turning' : 'countdown' } : {}),
            ...(swapVariant ? { swapPhase: step === count ? 'complete' : step === count - 1 && progress > 0 ? 'swapping' : 'waiting' } : {}),
            phase: time >= duration ? 'complete' : progress > 0 ? 'transition' : 'hold',
        };
    }
    function publish() {
        const state = snapshot();
        root.dataset.phase = state.phase;
        root.dataset.playing = String(playing);
        if (window.parent !== window) window.parent.postMessage(state, '*');
    }
    function tick(now) {
        if (!playing) return;
        position = currentTime();
        render(position);
        if (!config.loop && position >= duration) {
            playing = false;
            publish();
            return;
        }
        if (now - lastPublished >= 80) { publish(); lastPublished = now; }
        frame = requestAnimationFrame(tick);
    }
    function play(options = {}) {
        if (!ready) return;
        cancelAnimationFrame(frame);
        position = Number.isFinite(options.time) ? clamp(options.time, 0, duration) : currentTime();
        if (position >= duration) position = 0;
        originTime = position;
        startedAt = Number.isFinite(options.startedAt) ? options.startedAt : clock();
        playing = true;
        render(position);
        frame = requestAnimationFrame(tick);
        publish();
    }
    function pause(time) {
        position = Number.isFinite(time) ? clamp(time, 0, duration) : currentTime();
        playing = false;
        cancelAnimationFrame(frame);
        render(position);
        publish();
    }
    function seek(time) { pause(numeric(time, 0, duration, currentTime())); }
    function seekStep(step) { seek(Math.round(numeric(step, 0, lastModelStep, 0)) * (config.holdDuration + config.transitionDuration)); }
    function restart(options = {}) { play({ ...options, time: 0 }); }
    function remapTime(time, previousTiming) {
        const oldTime = clamp(time, 0, previousTiming.duration);
        if (oldTime >= previousTiming.duration) return duration;
        if (previousTiming.holdDuration === config.holdDuration
            && previousTiming.transitionDuration === config.transitionDuration) return clamp(oldTime, 0, duration);
        // Preserve the fraction of the current hold or transition.
        const cycle = Math.floor(oldTime / (previousTiming.holdDuration + previousTiming.transitionDuration));
        const within = oldTime - cycle * (previousTiming.holdDuration + previousTiming.transitionDuration);
        const offset = within < previousTiming.holdDuration
            ? within / previousTiming.holdDuration * config.holdDuration
            : config.holdDuration + (within - previousTiming.holdDuration) / previousTiming.transitionDuration * config.transitionDuration;
        return clamp(cycle * (config.holdDuration + config.transitionDuration) + offset, 0, duration);
    }

    function configure(next = {}, options = {}) {
        const resume = typeof options.playing === 'boolean' ? options.playing : playing;
        const time = Number.isFinite(options.time) ? options.time : currentTime();
        // The dashboard supplies the timing basis for its sampled time. This
        // also handles rapid edits before it receives the previous update.
        const supplied = options.timing;
        const previousTiming = supplied
            && [supplied.holdDuration, supplied.transitionDuration, supplied.duration].every(Number.isFinite)
            && supplied.holdDuration >= 0 && supplied.transitionDuration > 0 && supplied.duration > 0
            ? supplied : { holdDuration: config.holdDuration, transitionDuration: config.transitionDuration, duration };
        playing = false;
        cancelAnimationFrame(frame);
        config = {
            transitionDuration: numeric(next.transitionDuration ?? config.transitionDuration, 1, 5000, config.transitionDuration),
            holdDuration: numeric(next.holdDuration ?? config.holdDuration, 0, 10000, config.holdDuration),
            easing: typeof next.easing === 'string' && easingFor(next.easing) ? next.easing : config.easing,
            fontSize: numeric(next.fontSize ?? config.fontSize, 12, 96, config.fontSize),
            characterSpacing: numeric(next.characterSpacing ?? config.characterSpacing, 0, 8, config.characterSpacing),
            flapWidth: numeric(next.flapWidth ?? config.flapWidth, 0.6, 2, config.flapWidth),
            flapHeight: numeric(next.flapHeight ?? config.flapHeight, 1, 2.5, config.flapHeight),
            flapGap: numeric(next.flapGap ?? config.flapGap, 0, 0.5, config.flapGap),
            flapOuterGap: numeric(next.flapOuterGap ?? config.flapOuterGap, 0, 96, config.flapOuterGap),
            leadingFlagGap: numeric(next.leadingFlagGap ?? config.leadingFlagGap, 0, 96, config.leadingFlagGap),
            starScale: numeric(next.starScale ?? config.starScale, 0.25, 4, config.starScale),
            flapColor: normalizeColor(next.flapColor) || config.flapColor,
            detailColor: normalizeColor(next.detailColor) || config.detailColor,
            detailOpacity: numeric(next.detailOpacity ?? config.detailOpacity, 0, 1, config.detailOpacity),
            detailsVisible: typeof next.detailsVisible === 'boolean' ? next.detailsVisible : config.detailsVisible,
            backgroundColor: normalizeColor(next.backgroundColor) || config.backgroundColor,
            loop: typeof next.loop === 'boolean' ? next.loop : config.loop,
        };
        build();
        position = remapTime(time, previousTiming);
        // Editing a completed animation must never invoke play()'s replay behaviour.
        if (resume && position < duration) play({ ...options, time: position });
        else { render(position); publish(); }
    }

    async function init() {
        config = readDefaults();
        try { await document.fonts.load(`400 ${config.fontSize}px "Roboto Mono"`, word + '0123456789'); }
        catch { /* A network failure retains the monospaced system fallback. */ }
        build();
        ready = true;
        window.i12e = Object.freeze({ play, pause, restart, seek, seekStep, configure, getState: snapshot });
        window.addEventListener('message', event => {
            if (event.source !== window.parent || event.data?.type !== 'i12e:command') return;
            const data = event.data;
            if (data.action === 'configure') configure(data.config, data);
            else if (data.action === 'seek') seek(data.time);
            else if (data.action === 'seekStep') seekStep(data.step);
            else if (data.action === 'play') play(data);
            else if (data.action === 'pause') pause(data.time);
            else if (data.action === 'restart') restart(data);
            else if (data.action === 'status') publish();
        });
        motionPreference.addEventListener('change', event => { if (event.matches) seek(duration); });
        if (motionPreference.matches) seek(duration);
        else if (params.get('autoplay') === '0') seek(0);
        else play();
    }
    if (document.readyState === 'complete') init();
    else window.addEventListener('load', init, { once: true });
})();
